INSERT INTO dbo.Lessons (LessonId, ModuleId, Title, ContentHtml, MaterialUrl, ContentType, AttachmentFileId, SortOrder, IsPublished, EstimatedMinutes, CreatedAt) VALUES
('40000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001',N'Cài đặt môi trường & Sổ tay CS101',N'<h3>Hướng dẫn nhập môn CS101</h3><p>Sinh viên cài đặt Python 3.12, VS Code và làm quen biến, kiểu dữ liệu, cấu trúc rẽ nhánh và vòng lặp.</p>','/api/files/f0000000-0000-0000-0000-000000000001/content','PDF','f0000000-0000-0000-0000-000000000001',1,1,45,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000002',N'Big-O căn bản',N'<p>Phân tích thời gian chạy O(1), O(log n), O(n), O(n log n) và bộ nhớ phụ trợ.</p>',NULL,'TEXT',NULL,1,1,50,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000003',N'Khóa chính và khóa ngoại',N'<p>Thiết kế ràng buộc toàn vẹn tham chiếu giữa các bảng trong SQL Server.</p>',NULL,'TEXT',NULL,1,1,45,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000004','30000000-0000-0000-0000-000000000004',N'Waterfall và Agile',N'<p>So sánh mô hình thác nước và phát triển lặp ngắn hạn theo Scrum/Kanban.</p>',NULL,'TEXT',NULL,1,1,60,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000005','30000000-0000-0000-0000-000000000005',N'Bảy tầng OSI',N'<p>Vai trò và đơn vị dữ liệu giao thức qua 7 tầng Physical đến Application.</p>',NULL,'TEXT',NULL,1,1,55,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000006','30000000-0000-0000-0000-000000000006',N'Tác tử thông minh',N'<p>Kiến trúc Agent, Environment, Sensors, Actuators và hàm mục tiêu.</p>',NULL,'TEXT',NULL,1,1,50,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000007','30000000-0000-0000-0000-000000000007',N'HTTP và REST',N'<p>Phương thức GET/POST/PUT/PATCH/DELETE, status codes và hợp đồng RESTful API.</p>',NULL,'TEXT',NULL,1,1,60,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000008','30000000-0000-0000-0000-000000000008',N'Viết Project Charter',N'<p>Xác định phạm vi, cột mốc, ngân sách và các bên liên quan chính của dự án.</p>',NULL,'TEXT',NULL,1,1,45,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000009','30000000-0000-0000-0000-000000000009',N'CIA Triad',N'<p>Confidentiality, Integrity, Availability và phân tích mô hình mối đe dọa.</p>',NULL,'TEXT',NULL,1,1,40,DATEADD(day,-44,@Now)),
('40000000-0000-0000-0000-000000000010','30000000-0000-0000-0000-000000000010',N'Mô hình dịch vụ Cloud',N'<p>Phân biệt trách nhiệm quản trị giữa IaaS, PaaS và SaaS.</p>',NULL,'TEXT',NULL,1,0,45,DATEADD(day,-44,@Now));
